/bin/bash -lc "python3 - <<'PY'
import ast,hashlib,json,subprocess
from pathlib import Path
p=json.loads(Path('proposal.json').read_text())
r=json.loads(subprocess.run(['python3','/workspace/tools.py','resolve','run://r-001'],check=True,capture_output=True,text=True).stdout)
def validate(x,s,path='study'):
 types={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int,'number':(int,float)}
 if 'type' in s: assert isinstance(x,types[s['type']]),(path,'type')
 if 'const' in s: assert x==s['const'],(path,'const')
 if 'enum' in s: assert x in s['enum'],(path,'enum')
 if isinstance(x,str) and 'minLength' in s: assert len(x)>=s['minLength'],(path,'minLength')
 if isinstance(x,list):
  if 'minItems' in s: assert len(x)>=s['minItems'],(path,'minItems')
  for i,v in enumerate(x): validate(v,s.get('items',{}),f'{path}[{i}]')
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'required')
  if s.get('additionalProperties') is False: assert set(x)<=set(s.get('properties',{})),(path,'extra')
  for k,v in x.items(): validate(v,s.get('properties',{}).get(k,{}),path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert all(c['parent_ref'] in allowed for c in p['study']['contrasts'])
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
original=ast.parse(Path('history_g0_r0063_uncentered_native.py').read_text())
old_cls=next(n for n in original.body if isinstance(n,ast.ClassDef) and n.name=='Model')
old_methods={n.name:n for n in old_cls.body if isinstance(n,ast.FunctionDef)}
imports={'torch','unirank'}
reference=None
for v in p['variants']:
 path=Path(v['file']); assert path.name==v['file'] and path.suffix=='.py'
 text=path.read_text(); tree=ast.parse(text); compile(tree,str(path),'exec')
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert config==v['config']
 assert not (set(config)&{'train_seed','epochs','batch_size','learning_rate','dense_learning_rate','sparse_learning_rate','history_limit','loss_weights'})
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 args=methods['__init__'].args
 defaults=dict(zip([a.arg for a in args.args][-len(args.defaults):],args.defaults))
 for key in ('product_vjp_removal','block_aux_adapter_context_grad'):
  assert ast.literal_eval(defaults[key])==config[key]
 for name,method in methods.items():
  if name not in ('__init__','_context_history_correction','_normalize_product'):
   assert ast.dump(method)==ast.dump(old_methods[name]),name
 def learned_calls(method):
  return [ast.dump(n) for n in ast.walk(method) if isinstance(n,ast.Call) and ((isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn') or (isinstance(n.func,ast.Name) and n.func.id=='FeatureEmbeddingDict'))]
 assert learned_calls(methods['__init__'])==learned_calls(old_methods['__init__'])
 for node in ast.walk(tree):
  if isinstance(node,ast.Import): assert all(a.name.split('.')[0] in imports for a in node.names)
  if isinstance(node,ast.ImportFrom): assert node.module.split('.')[0] in imports
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name): assert node.func.id not in ('open','eval','exec','compile','__import__')
 stripped={name:ast.dump(method) for name,method in methods.items() if name"'!='"'__init__'}
 if reference is None: reference=stripped
 else: assert stripped==reference
 sha=hashlib.sha256(path.read_bytes()).hexdigest(); assert sha in v['note']
 print(v['name'],'syntax/config/ownership/inherited-method checks passed',sha)
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
print('Study schema, evidence IDs, frozen protocol, four-cell factorial and baseline identity: passed')
print('All nonconstructor methods are identical across cells; module constructors match the native ancestor')
PY"

